namespace LiveScore.WebApi.Features.Matches
{
    using System;
    using System.Collections.Generic;
    using System.Threading.Tasks;
    using LiveScore.Features.Matches;
    using LiveScore.Features.Matches.Models;    
    using Microsoft.AspNetCore.Mvc;

    [Route("api/[controller]")]
    [ApiController]
    public class MatchController : ControllerBase
    {
        private readonly IMatchService matchService;

        public MatchController(IMatchService matchService)
        {
            this.matchService = matchService;
        }

        [HttpGet("GetMatches")]
        public async Task<IEnumerable<IMatch>> GetMatches(
            int sportId,
            DateTime from,
            DateTime to,
            TimeSpan timeZone,
            string language = "en-US")
        {  
            return await matchService.GetMatches(sportId, from, to, timeZone, language);
        }

        [HttpGet("GetMatch")]
        public async Task<IMatch> GetMatch(
            int sportId,
            string matchId,
            string language = "en-US")
        {
            var match= await matchService.GetMatch(sportId, matchId, language);

            if (match == null)
            {
                throw new InvalidOperationException($"Not found {matchId}");
            }

            return match;
        }
    }
}